import 'package:isar/isar.dart';

part 'isar_schemas.g.dart';
// ^ generated by: dart run build_runner build --delete-conflicting-outputs

/// Library index only - this never stores audio bytes, only paths + tags.
/// Mirrors the "Song Table" in the design doc.
@collection
class SongRecord {
  Id id = Isar.autoIncrement;

  @Index(unique: true, replace: true)
  late String path;

  late String filename;
  int durationMs = 0;
  String? artist;
  String? album;
  String? title;
  late DateTime modified;
  String? contentHash;
  String? artworkPath;
  int? metadataId; // FK -> MetadataRecord.id
  bool favorite = false;
  int playCount = 0;
  double? rating;
  bool hidden = false;
  int? bitrate;
  String? codec;
  int? sizeBytes;
}

/// Mirrors the "Metadata Table".
@collection
class MetadataRecord {
  Id id = Isar.autoIncrement;

  late String officialTitle;
  late String officialArtist;
  String? album;
  String? genre;
  int? year;
  int? track;
  String? artworkUrl;
  double confidence = 0.0;
  late String source;
}

/// Mirrors the "Artist Table". Canonical name after Smart Artist Merge.
@collection
class ArtistRecord {
  Id id = Isar.autoIncrement;

  @Index(unique: true, replace: true)
  late String name;

  String? artworkPath;
  String? biography;
  int songCount = 0;
}

/// Mirrors the "Album Table". Canonical title after Smart Album Merge.
@collection
class AlbumRecord {
  Id id = Isar.autoIncrement;

  late int artistId;
  late String title;
  String? artworkPath;
  int? year;
}

/// Mirrors "History".
@collection
class HistoryRecord {
  Id id = Isar.autoIncrement;

  late int songId;
  late DateTime playedAt;
  int listenedMs = 0;
  bool skipped = false;
  bool completed = false;
}

/// Mirrors "Playlists" (junction table Playlist <-> Song <-> Position).
@collection
class PlaylistRecord {
  Id id = Isar.autoIncrement;

  late String name;
  List<int> songIdsOrdered = []; // song ids in playlist order
  bool isAuto = false;
  bool isAiGenerated = false;
}
